use std::io

fn main() {
    let text = io.read_to_string(io.stdin()) ?? ""
    let lines = text.lines()
    let mut cap = 1
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut first = true
    for line in lines {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>() ?? 0
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>() ?? 0
            let v = parts[2].parse::<int>() ?? 0
            let mut nk: Vec<int> = [k]
            let mut nv: Vec<int> = [v]
            let mut i = 0
            while i < keys.len() {
                if keys[i] != k {
                    nk.push(keys[i])
                    nv.push(vals[i])
                }
                i += 1
            }
            if nk.len() as int > cap {
                println("evict ${nk[nk.len() - 1]}")
                nk.pop()
                nv.pop()
            }
            keys = nk
            vals = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>() ?? 0
            let mut found = -1
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    found = vals[i]
                } else {
                    nk.push(keys[i])
                    nv.push(vals[i])
                }
                i += 1
            }
            if found != -1 || nk.len() < keys.len() {
                nk.insert(0, k)
                nv.insert(0, found)
                keys = nk
                vals = nv
            }
            println("${found}")
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < keys.len() {
                    if i > 0 {
                        out = out + " "
                    }
                    out = out + "${keys[i]}"
                    i += 1
                }
                println(out)
            }
        }
    }
}

